"""AQS-SITE-003 site access and dock check (X-BLD-07, A-M-212). AQS-SITE-001 dock geometry (params.py) against the AASHTO WB-67 design
vehicle and ISO 668 containers; freight elevator and equipment hatch against the largest unit that must reach each basement level
(AQS-BLD-013 rows, need-based envelopes). Apron depth = 1.5 x WB-67 length for a straight back-in (A-M-212; swept-path check at the parcel)."""
import json, os, sys, math
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R); sys.path.insert(0, os.path.join(R, 'models/freecad'))
from flow_graph.param.refs import cite
for k in ('AASHTO_GB7', 'ISO668_2020', 'ASME_B30_2'): cite(k)
import params as P
WB = dict(L=22400, W=2590, H=4110, R=13700); C40 = (12192, 2438, 2896); C20 = (6058, 2438, 2591)
U = json.load(open('flow_graph/placement_seed.json'))['units'] + json.load(open('flow_graph/placement_study.json'))['units']
big = {}
for u in U:
    z = u.get('size_mm'); lv = u.get('level')
    if z and lv in ('L-1', 'L-2') and len(z) >= 3 and not u.get('fixed_feature'):
        b = u['unit_id'].split('/')[0]; pl = sorted(z[:2])
        if b not in big or pl[1] > big[b][1]: big[b] = (pl[0], pl[1], z[2], lv)
lg = sorted(big.items(), key=lambda x: -x[1][1])[:5]
ew = sorted([P.ELEV_DOCK_L, P.ELEV_DOCK_W])
over = [(b, v) for b, v in big.items() if v[0] > ew[0] - 200 or v[1] > ew[1] - 200]
hL = max((v[1] for b, v in over), default=0) + 600; hW = max((v[0] for b, v in over), default=0) + 600
C = [('Dock door width', P.DOCK_DOOR_W, WB['W'] + 2*300, 'WB-67 width + 300 mm each side'),
     ('Dock door height', getattr(P, 'DOCK_DOOR_H', 0), WB['H'] + 150, 'WB-67 height + 150 mm'),
     ('Apron depth north of the wall', P.DOCK_APRON_N, 1.5*WB['L'], '1.5 x WB-67 length (A-M-212)'),
     ('Apron width', max(P.DOCK_L*P.DOCK_COUNT, 12000, getattr(P, 'DOCK_APRON_W', 0)), 2*WB['R'] - 4000, 'turning: 2 x 13.7 m radius less the in-swing allowance'),
     ('Dock space length (20 ft container or its contents)', P.DOCK_L, C20[0] + 2*600, 'ISO 668 1CC + 600 mm each end'),
     ('Dock space width', P.DOCK_W, C20[1] + 2*1500, 'container + forklift aisle 1.5 m each side')]
md = ['# Site access and dock check', '', 'Document number: AQS-SITE-003', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-BLD-07. Generated by `docs-authority/_site_access.py`. Study. A-M-212.', '',
 'Design vehicle AASHTO WB-67 (22.4 x 2.59 x 4.11 m, 13.7 m turning radius); containers ISO 668 1AA/1AAA 40 ft and 1CC 20 ft. A 40 ft container stays on its trailer at the door and is unloaded there.', '',
 '| Check | Provided mm | Required mm | Basis | Result |', '|---|---|---|---|---|'] + [f'| {a} | {p:.0f} | {r:.0f} | {b} | {"pass" if p >= r else "FAIL"} |' for a, p, r, b in C]
md += ['', '## Freight elevator and equipment hatch', '', f'Freight elevator car {P.ELEV_DOCK_L} x {P.ELEV_DOCK_W} mm. Largest basement units (plan, sorted):', '', '| Unit | Level | Plan short x long mm | Height mm |', '|---|---|---|---|'] + [f'| {b} | {v[3]} | {v[0]:.0f} x {v[1]:.0f} | {v[2]:.0f} |' for b, v in lg]
md += ['', f'{len(over)} basement units do not fit the elevator with 100 mm clearance each side; they go down an equipment hatch of {hL:.0f} x {hW:.0f} mm in the L0 slab beside the dock, served by the L0 hoist (AQS-BLD-015), with a removable 2 h rated cover (AQS-HSE-001 horizontal assembly). Units taller than the storey are installed in sections.' if over else '', '',
 'Changes made: DOCK_APRON_N 6,000 -> 34,000 mm and new DOCK_DOOR_H 4,300 mm and DOCK_APRON_W = PLATE_L in `models/freecad/params.py`.']
open('docs-authority/SITE_ACCESS_CHECK.md', 'w').write('\n'.join(md) + '\n')
json.dump(dict(hatch_mm=[hL, hW], units_by_hatch=sorted(b for b, v in over)), open('docs-authority/inventory/SITE_ACCESS.json', 'w'), indent=1)
print([(a, p, r) for a, p, r, b in C if p < r], len(over), hL, hW)
